(function(root){
 'use strict';
 const $=id=>document.getElementById(id),fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d}):'Not recorded';
 const metrics=[
  {key:'vapor',id:'history-production',title:'history-production-title',label:'Clean vapor',unit:'L',divisor:1000,digits:4,cumulative:'cumulativeVapor'},
  {key:'liquid',id:'history-consumption',title:'history-consumption-title',label:'E-liquid consumed',unit:'mL',digits:1,cumulative:'cumulativeLiquid'},
  {key:'energy',id:'history-energy-chart',title:'history-energy-title',label:'Energy consumed',unit:'Wh',digits:4,cumulative:'cumulativeEnergy'},
  {key:'credits',id:'history-credits-chart',title:'history-credits-title',label:'Credits earned',unit:'Credits',digits:1,cumulative:'cumulativeCredits'},
  {key:'largest',id:'history-largest-chart',title:'history-largest-title',label:'Largest completed clean puff',unit:'L',divisor:1000,digits:4,record:true},
  {key:'longest',id:'history-longest-chart',title:'history-longest-title',label:'Longest qualifying clean draw',unit:'s',digits:2,record:true},
  ...['session','firing','throughput','liquidRate','averagePower','throughputBonus'].map((key,i)=>({key,id:`history-${key}-chart`,title:`history-${key}-title`,label:['Session duration','Firing duration','Average clean throughput','Average liquid consumption','Average firing power','Throughput bonus'][i],unit:['s','s','L/s','mL/s','W','×'][i],digits:[2,2,5,3,2,3][i],pace:true})),
  {key:'smoke',id:'history-smoke-chart',title:'history-smoke-title',label:'Smoke produced',unit:'L',divisor:1000,digits:4}
 ];
 let history,mode='round',key='',selected=0,scale,series;
 function values(m){if(m.pace)return CloudGame.H.metricSeries(history,m.key,mode==='total').values;let running=m.cumulative?Math.max(0,(history.totals[m.key]||0)-history.rounds.reduce((sum,p)=>sum+(Number.isFinite(p[m.key])?p[m.key]:0),0)):0;return history.rounds.map(p=>{if(!Number.isFinite(p[m.key]))return null;let v=p[m.key];if(mode==='total'){if(m.cumulative){running+=v;v=running;}else if(m.record){running=Math.max(running,v);v=running;}else{running+=v;v=running;}}return v/(m.divisor||1);});}
 function chart(m){const list=history.rounds,data=series[m.key],max=Math.max(.001,...data.filter(Number.isFinite))*1.15,first=list[0].number,last=list.at(-1).number,x=n=>first===last?308:58+500*(n-first)/(last-first),y=v=>160-130*v/max;scale={x};let svg=`<title>${m.label} (${m.unit}), ${mode==='round'?'per session':m.record?'best measured to date':'cumulative measured'}</title>`;
  for(let i=0;i<4;i++){const yy=160-i*130/3;svg+=`<line x1="58" x2="558" y1="${yy}" y2="${yy}" class="plot-grid"/><text x="50" y="${yy+4}" text-anchor="end">${fmt(max*i/3,m.digits)}</text>`;}
  for(const round of [...new Set([first,Math.round((first+last)/2),last])])svg+=`<text x="${x(round)}" y="181" text-anchor="middle">${round}</text>`;
  svg+='<text x="308" y="204" text-anchor="middle">SESSION</text>';let path='',continuing=false;
  list.forEach((p,i)=>{const v=data[i];if(v===null){continuing=false;return;}path+=`${continuing?'L':'M'}${x(p.number).toFixed(2)},${y(v).toFixed(2)} `;continuing=true;svg+=`<circle cx="${x(p.number)}" cy="${y(v)}" r="3" class="history-dot ${m.key}"/>`;});
  svg+=`<path d="${path}" class="history-line ${m.key}"/><line data-history-cursor x1="58" x2="58" y1="25" y2="160" class="plot-cursor"/>`;if(data.every(v=>v===null))svg+='<text x="308" y="95" text-anchor="middle">Not recorded yet</text>';$(m.id).innerHTML=svg;
 }
 function inspect(index){if(!history?.rounds.length)return;selected=Math.max(0,Math.min(history.rounds.length-1,index));const p=history.rounds[selected];$('history-scrub').value=selected;$('history-reading').textContent=`Session ${p.number}${mode==='total'?' · cumulative / best recorded':''}: `+metrics.map(m=>`${m.label}: ${series[m.key][selected]===null?'Not recorded':fmt(series[m.key][selected],m.digits)+' '+m.unit}`).join(' · ');for(const m of metrics){const line=$(m.id).querySelector('[data-history-cursor]');if(line){line.setAttribute('x1',scale.x(p.number));line.setAttribute('x2',scale.x(p.number));}}}
 function render(state){history=state.history;const next=JSON.stringify([mode,history.rounds,history.totals]);if(next===key)return;key=next;const count=history.rounds.length;for(const id of ['history-charts','history-scrub-label','history-reading'])$(id).hidden=!count;$('history-empty').hidden=count>0;$('history-vapor').textContent=fmt(history.totals.vapor/1000,4)+' L';$('history-liquid').textContent=history.totals.knownLiquid?fmt(history.totals.liquid,1)+' mL':'Not recorded';$('history-energy').textContent=history.totals.knownEnergy?fmt(history.totals.energy,4)+' Wh':'Not recorded';$('history-credits').textContent=fmt(history.totals.credits,1);$('history-round').setAttribute('aria-pressed',mode==='round');$('history-total').setAttribute('aria-pressed',mode==='total');
  for(const m of metrics)$(m.title).textContent=`${m.key==='throughputBonus'?'Throughput bonus per session':mode==='round'?m.label+' per session':m.pace?(['session','firing'].includes(m.key)?'Cumulative '+m.label.toLowerCase():'Weighted '+m.label.toLowerCase()):m.record?'Best recorded '+m.label.toLowerCase():'Cumulative '+m.label.toLowerCase()} · ${m.unit}`;
  $('history-note').textContent=`${history.totals.count} recorded sessions. Missing measurements are gaps, never zero. Older saves did not store every metric; only the latest saved result can be recovered. Cumulative mode sums volume, consumption and Credits; largest puff and longest draw show running records. ${history.archived?'Showing latest '+count+' sessions. Smoke totals and puff/duration records cover the displayed history; older stored resource totals remain included.':''}`;
  const coverage=['session','firing','throughput','liquidRate','averagePower','throughputBonus'].map(k=>{const a=CloudGame.H.metricSeries(history,k);return `${metrics.find(m=>m.key===k).label}: ${k==='throughputBonus'?a.values.filter(Number.isFinite).length:a.count}/${count}`;}).join(' · ');$('history-note').textContent+=' Pace graphs use the displayed measured sessions only; cumulative rates divide paired totals, never average averages. Coverage — '+coverage+'. Throughput multipliers remain per-session.';if(!count)return;series=Object.fromEntries(metrics.map(m=>[m.key,values(m)]));for(const m of metrics)chart(m);$('history-scrub').max=count-1;inspect(count-1);
 }
 function init(){for(const [id,next]of [['history-round','round'],['history-total','total']])$(id).onclick=()=>{mode=next;key='';render({history});};$('history-scrub').oninput=e=>inspect(Number(e.target.value));for(const m of metrics)$(m.id).onpointermove=e=>{if(!history?.rounds.length)return;const rect=$(m.id).getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*580;let best=0;history.rounds.forEach((p,i)=>{if(Math.abs(scale.x(p.number)-x)<Math.abs(scale.x(history.rounds[best].number)-x))best=i;});inspect(best);};}
 root.ProgressUI={init,render};
})(window);
